(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-challenge-examples-basic"]={"id":"unit22-challenge-examples-basic","unitId":"2-2","chapterIds":["2-2"],"unitType":"basic","group":"2-2단원 · 3. 시장 대 줄 서기","name":"어려운 소재 · 쉬운 예시 OX","level":"기본","desc":"새 예시로 개념을 이해하고 OX만 골라요.","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","readingBlock":"challenge","readingChunk":"examples","parts":[{"name":"U22-E06 · 낼 마음과 낼 수 있는 돈은 달라요","items":[{"id":"U22-E06-B1","type":"ox","answer":"O","changed":"준서가 더 비싼 값을 냈다고 해서 세라보다 공연을 더 보고 싶어 했다고 볼 수는 없다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"세라는 공연을 무척 보고 싶어도 돈이 부족해서 비싼 표를 사지 못해요. 준서가 비싼 표를 샀다는 사실만으로 두 사람이 공연을 얼마나 좋아하는지 비교할 수는 없어요.","paragraphCount":2,"readingLabel":"12문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 12문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 12문단]\n하지만 이러한 주장은 설득력이 없다. 우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다. 어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다. 시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다. 셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다. 그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n세라는 공연을 무척 보고 싶지만 비싼 표를 살 돈이 없다. 준서는 공연에 큰 관심은 없지만 가진 돈이 많아 비싼 표를 샀다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["정도"],"evidence":{"title":"낼 마음과 낼 수 있는 돈은 달라요","statement":"준서가 더 비싼 값을 냈다고 해서 세라보다 공연을 더 보고 싶어 했다고 볼 수는 없다.","explanation":"세라는 공연을 무척 보고 싶어도 돈이 부족해서 비싼 표를 사지 못해요. 준서가 비싼 표를 샀다는 사실만으로 두 사람이 공연을 얼마나 좋아하는지 비교할 수는 없어요.","valid":["L12:3","L12:4","L12:5","L12:6"],"sources":[{"id":"L12","title":"줄 서기를 돈으로 살 수 있을까","label":"12문단","sentences":[{"id":"L12:1","text":"하지만 이러한 주장은 설득력이 없다.","paragraph":0,"memberIds":["L12:1"],"topic":"필자는 11문단에서 예상한 시장 옹호자의 반론, 곧 “비싼 값을 내는 사람이 공연을 가장 원하므로 시장에 맡기자”는 주장에 설득력이 없다고 본다."},{"id":"L12:2","text":"우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다.","paragraph":0,"memberIds":["L12:2"],"topic":"목표가 '모두의 만족을 최대로'라고 쳐도, 시장이 줄 서기보다 더 믿을 만하지 않을 수도 있다."},{"id":"L12:3","text":"어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다.","paragraph":0,"memberIds":["L12:3"],"topic":"돈을 많이 낸다고 해서 꼭 그걸 더 좋아한다는 뜻은 아니기 때문이다."},{"id":"L12:4","text":"시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다.","paragraph":0,"memberIds":["L12:4"],"topic":"가격에는 '얼마나 사고 싶은지(마음)'뿐 아니라 '돈이 얼마나 있는지(능력)'도 들어 있다."},{"id":"L12:5","text":"셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.","paragraph":0,"memberIds":["L12:5"],"topic":"공연이나 경기를 가장 보고 싶은 사람도 표 살 돈이 없을 수 있다."},{"id":"L12:6","text":"그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","paragraph":0,"memberIds":["L12:6"],"topic":"반대로, 가장 비싼 표를 산 사람이 그 공연을 별로 좋아하지 않을 수도 있다."}]}]},"editorSourceVersion":"93397cb7e0d04c8a0e5034f563af21a0905f4dcd1003c3890a82b1b067204348"},{"id":"U22-E06-B2","type":"ox","answer":"X","changed":"준서가 더 비싼 값을 냈으므로 반드시 세라보다 공연을 더 보고 싶어 했을 것이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"세라는 공연을 무척 보고 싶어도 돈이 부족해서 비싼 표를 사지 못해요. 준서가 비싼 표를 샀다는 사실만으로 두 사람이 공연을 얼마나 좋아하는지 비교할 수는 없어요.","paragraphCount":2,"readingLabel":"12문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 12문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 12문단]\n하지만 이러한 주장은 설득력이 없다. 우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다. 어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다. 시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다. 셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다. 그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n세라는 공연을 무척 보고 싶지만 비싼 표를 살 돈이 없다. 준서는 공연에 큰 관심은 없지만 가진 돈이 많아 비싼 표를 샀다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["정도"],"evidence":{"title":"낼 마음과 낼 수 있는 돈은 달라요","statement":"준서가 더 비싼 값을 냈어도 세라보다 공연을 더 보고 싶어 했다고 할 수는 없다.","explanation":"세라는 공연을 무척 보고 싶어도 돈이 부족해서 비싼 표를 사지 못해요. 준서가 비싼 표를 샀다는 사실만으로 두 사람이 공연을 얼마나 좋아하는지 비교할 수는 없어요.","valid":["L12:3","L12:4","L12:5","L12:6"],"sources":[{"id":"L12","title":"줄 서기를 돈으로 살 수 있을까","label":"12문단","sentences":[{"id":"L12:1","text":"하지만 이러한 주장은 설득력이 없다.","paragraph":0,"memberIds":["L12:1"],"topic":"필자는 11문단에서 예상한 시장 옹호자의 반론, 곧 “비싼 값을 내는 사람이 공연을 가장 원하므로 시장에 맡기자”는 주장에 설득력이 없다고 본다."},{"id":"L12:2","text":"우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다.","paragraph":0,"memberIds":["L12:2"],"topic":"목표가 '모두의 만족을 최대로'라고 쳐도, 시장이 줄 서기보다 더 믿을 만하지 않을 수도 있다."},{"id":"L12:3","text":"어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다.","paragraph":0,"memberIds":["L12:3"],"topic":"돈을 많이 낸다고 해서 꼭 그걸 더 좋아한다는 뜻은 아니기 때문이다."},{"id":"L12:4","text":"시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다.","paragraph":0,"memberIds":["L12:4"],"topic":"가격에는 '얼마나 사고 싶은지(마음)'뿐 아니라 '돈이 얼마나 있는지(능력)'도 들어 있다."},{"id":"L12:5","text":"셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.","paragraph":0,"memberIds":["L12:5"],"topic":"공연이나 경기를 가장 보고 싶은 사람도 표 살 돈이 없을 수 있다."},{"id":"L12:6","text":"그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","paragraph":0,"memberIds":["L12:6"],"topic":"반대로, 가장 비싼 표를 산 사람이 그 공연을 별로 좋아하지 않을 수도 있다."}]}]},"claimEdits":[{"start":12,"end":21,"before":"냈으므로 반드시 ","after":"냈어도 "},{"start":38,"end":45,"before":"했을 것이다.","after":"했다고 할 수는 없다."}],"editorSourceVersion":"d010d919cd3dc7776411e9680b0be7d5f368bf3236f2cac97c0aad0684c3b50b"}]},{"name":"U22-E07 · 비싼 좌석이 열정의 완벽한 증거일까요","items":[{"id":"U22-E07-B1","type":"ox","answer":"O","changed":"비싼 좌석을 살 수 있다고 야구를 더 좋아하는 것은 아니다. 줄을 선 학생은 야구를 매우 좋아해도 비싼 좌석을 살 돈이 없다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"비싼 좌석을 사려면 돈이 있어야 해요. 그래서 얼마짜리 좌석을 샀는지만 보고 야구를 얼마나 좋아하는지 정확히 알 수는 없어요.","paragraphCount":2,"readingLabel":"13문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 13문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 13문단]\n예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다. 그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다. 이렇듯 비싼 관람석에 앉을 수 있는 경제적 능력은 경기를 향한 열정보다는 주머니 사정과 관계가 깊을 수 있다. 오히려 경제적 여유는 없지만 선발 출전 선수들의 평균 타율을 전부 꿰고 있는 팬들, 특히 젊은 팬들이 그들보다 야구를 좋아하는 것만은 확실하다. 시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다. 어떨 때는 공연을 관람하거나 야구 경기를 보기 위해 자발적으로 줄을 서고자 하는 태도가 가격을 지불하고자 하는 태도보다 관람을 정말 원하는 사람을 나타내는 지표일 수 있다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n한 학생은 야구를 매우 좋아하지만 비싼 좌석을 살 돈이 없어 일찍부터 줄을 섰다. 다른 관객은 비싼 좌석에 늦게 도착해 경기가 끝나기 전에 떠났다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["정도"],"evidence":{"title":"비싼 좌석이 열정의 완벽한 증거일까요","statement":"비싼 좌석을 살 수 있다고 야구를 더 좋아하는 것은 아니다. 줄을 선 학생은 야구를 매우 좋아해도 비싼 좌석을 살 돈이 없다.","explanation":"비싼 좌석을 사려면 돈이 있어야 해요. 그래서 얼마짜리 좌석을 샀는지만 보고 야구를 얼마나 좋아하는지 정확히 알 수는 없어요.","valid":["L13:3","L13:5","L13:6"],"sources":[{"id":"L13","title":"줄 서기를 돈으로 살 수 있을까","label":"13문단","sentences":[{"id":"L13:1","text":"예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다.","paragraph":0,"memberIds":["L13:1"],"topic":"예를 들어 필자는 야구장에서 이런 사람들을 자주 본다. 늦게 와서 비싼 자리에 앉았다가 일찍 가 버리는 사람들이다."},{"id":"L13:2","text":"그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다.","paragraph":0,"memberIds":["L13:2"],"topic":"그럴 때 필자는 '저 사람들, 야구를 정말 좋아하는 걸까?' 하고 의심한다."},{"id":"L13:3","text":"이렇듯 비싼 관람석에 앉을 수 있는 경제적 능력은 경기를 향한 열정보다는 주머니 사정과 관계가 깊을 수 있다.","paragraph":0,"memberIds":["L13:3"],"topic":"이처럼 비싼 자리에 앉는 건 경기를 좋아하는 마음 때문이라기보다 돈이 많아서일 수 있다."},{"id":"L13:4","text":"오히려 경제적 여유는 없지만 선발 출전 선수들의 평균 타율을 전부 꿰고 있는 팬들, 특히 젊은 팬들이 그들보다 야구를 좋아하는 것만은 확실하다.","paragraph":0,"memberIds":["L13:4"],"topic":"오히려 돈은 없어도 선발 선수들의 타율(안타를 치는 비율)을 다 외우는 팬, 특히 젊은 팬들이 그 사람들보다 야구를 더 좋아하는 건 확실하다."},{"id":"L13:5","text":"시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다.","paragraph":0,"memberIds":["L13:5"],"topic":"가격에는 마음과 돈(능력)이 같이 들어 있다. 그래서 가격만 보고는 누가 가장 좋아하는지 정확히 알 수 없다. 가격은 정확하지 않은 자(불완전한 지표)다."},{"id":"L13:6","text":"어떨 때는 공연을 관람하거나 야구 경기를 보기 위해 자발적으로 줄을 서고자 하는 태도가 가격을 지불하고자 하는 태도보다 관람을 정말 원하는 사람을 나타내는 지표일 수 있다.","paragraph":0,"memberIds":["L13:6"],"topic":"때로는 '몇 시간이라도 줄 서겠다'는 마음이 '돈을 내겠다'는 마음보다 진짜 팬을 더 잘 보여 줄 수 있다."}]}]},"editorSourceVersion":"01b49a313ae21c5f48eb03faa145ae3f65157bcd81999480ae974008e26128eb"},{"id":"U22-E07-B2","type":"ox","answer":"X","changed":"비싼 좌석을 산 관객은 줄을 선 학생보다 반드시 야구를 더 좋아한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"비싼 좌석을 사려면 돈이 있어야 해요. 그래서 얼마짜리 좌석을 샀는지만 보고 야구를 얼마나 좋아하는지 정확히 알 수는 없어요.","paragraphCount":2,"readingLabel":"13문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 13문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 13문단]\n예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다. 그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다. 이렇듯 비싼 관람석에 앉을 수 있는 경제적 능력은 경기를 향한 열정보다는 주머니 사정과 관계가 깊을 수 있다. 오히려 경제적 여유는 없지만 선발 출전 선수들의 평균 타율을 전부 꿰고 있는 팬들, 특히 젊은 팬들이 그들보다 야구를 좋아하는 것만은 확실하다. 시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다. 어떨 때는 공연을 관람하거나 야구 경기를 보기 위해 자발적으로 줄을 서고자 하는 태도가 가격을 지불하고자 하는 태도보다 관람을 정말 원하는 사람을 나타내는 지표일 수 있다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n한 학생은 야구를 매우 좋아하지만 비싼 좌석을 살 돈이 없어 일찍부터 줄을 섰다. 다른 관객은 비싼 좌석에 늦게 도착해 경기가 끝나기 전에 떠났다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["정도"],"evidence":{"title":"비싼 좌석이 열정의 완벽한 증거일까요","statement":"비싼 좌석을 산 관객이 줄을 선 학생보다 반드시 야구를 더 좋아하는 것은 아니다.","explanation":"비싼 좌석을 사려면 돈이 있어야 해요. 그래서 얼마짜리 좌석을 샀는지만 보고 야구를 얼마나 좋아하는지 정확히 알 수는 없어요.","valid":["L13:3","L13:5","L13:6"],"sources":[{"id":"L13","title":"줄 서기를 돈으로 살 수 있을까","label":"13문단","sentences":[{"id":"L13:1","text":"예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다.","paragraph":0,"memberIds":["L13:1"],"topic":"예를 들어 필자는 야구장에서 이런 사람들을 자주 본다. 늦게 와서 비싼 자리에 앉았다가 일찍 가 버리는 사람들이다."},{"id":"L13:2","text":"그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다.","paragraph":0,"memberIds":["L13:2"],"topic":"그럴 때 필자는 '저 사람들, 야구를 정말 좋아하는 걸까?' 하고 의심한다."},{"id":"L13:3","text":"이렇듯 비싼 관람석에 앉을 수 있는 경제적 능력은 경기를 향한 열정보다는 주머니 사정과 관계가 깊을 수 있다.","paragraph":0,"memberIds":["L13:3"],"topic":"이처럼 비싼 자리에 앉는 건 경기를 좋아하는 마음 때문이라기보다 돈이 많아서일 수 있다."},{"id":"L13:4","text":"오히려 경제적 여유는 없지만 선발 출전 선수들의 평균 타율을 전부 꿰고 있는 팬들, 특히 젊은 팬들이 그들보다 야구를 좋아하는 것만은 확실하다.","paragraph":0,"memberIds":["L13:4"],"topic":"오히려 돈은 없어도 선발 선수들의 타율(안타를 치는 비율)을 다 외우는 팬, 특히 젊은 팬들이 그 사람들보다 야구를 더 좋아하는 건 확실하다."},{"id":"L13:5","text":"시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다.","paragraph":0,"memberIds":["L13:5"],"topic":"가격에는 마음과 돈(능력)이 같이 들어 있다. 그래서 가격만 보고는 누가 가장 좋아하는지 정확히 알 수 없다. 가격은 정확하지 않은 자(불완전한 지표)다."},{"id":"L13:6","text":"어떨 때는 공연을 관람하거나 야구 경기를 보기 위해 자발적으로 줄을 서고자 하는 태도가 가격을 지불하고자 하는 태도보다 관람을 정말 원하는 사람을 나타내는 지표일 수 있다.","paragraph":0,"memberIds":["L13:6"],"topic":"때로는 '몇 시간이라도 줄 서겠다'는 마음이 '돈을 내겠다'는 마음보다 진짜 팬을 더 잘 보여 줄 수 있다."}]}]},"claimEdits":[{"start":9,"end":13,"before":"관객은 ","after":"관객이 "},{"start":33,"end":38,"before":"좋아한다.","after":"좋아하는 것은 아니다."}],"editorSourceVersion":"9625b878a96b9c47e63245fd03dad94a0fb06885de66430de5062464b4dc2e8f"}]},{"name":"U22-E08 · 돈이 많을 때와 시간이 많을 때","items":[{"id":"U22-E08-B1","type":"ox","answer":"O","changed":"경매에서는 돈을 내려는 마음과 낼 수 있는 돈이 중요하다. 줄 서기에서는 기다리려는 마음과 기다릴 수 있는 시간이 중요하다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"가람은 돈이 많아 경매에서 유리하고, 나래는 시간이 많아 줄 서기에서 유리해요. 돈을 내고 싶어도 돈이 없을 수 있고, 기다리고 싶어도 시간이 없을 수 있어요.","paragraphCount":2,"readingLabel":"14문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 14문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 14문단]\n암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다. 맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다. 시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다. 그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n한정된 물건을 경매로 나누거나 줄을 세워 나누려 한다. 가람은 돈이 많지만 기다릴 시간이 없고, 나래는 돈은 적지만 기다릴 시간이 많다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["비교"],"evidence":{"title":"돈이 많을 때와 시간이 많을 때","statement":"경매에서는 돈을 내려는 마음과 낼 수 있는 돈이 중요하다. 줄 서기에서는 기다리려는 마음과 기다릴 수 있는 시간이 중요하다.","explanation":"가람은 돈이 많아 경매에서 유리하고, 나래는 시간이 많아 줄 서기에서 유리해요. 돈을 내고 싶어도 돈이 없을 수 있고, 기다리고 싶어도 시간이 없을 수 있어요.","valid":["L14:2","L14:3","L14:4"],"sources":[{"id":"L14","title":"줄 서기를 돈으로 살 수 있을까","label":"14문단","sentences":[{"id":"L14:1","text":"암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다.","paragraph":0,"memberIds":["L14:1"],"topic":"암표 거래를 옹호하는 사람들은 “줄 서기도 시간이 많은 사람에게 유리한 차별이다”라고 비판한다."},{"id":"L14:2","text":"맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다.","paragraph":0,"memberIds":["L14:2"],"topic":"필자는 그 지적을 인정한다. 다만 시장도 돈 많은 사람에게 유리하므로, 줄 서기에만 있는 문제는 아니라고 말한다."},{"id":"L14:3","text":"시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다.","paragraph":0,"memberIds":["L14:3"],"topic":"시장은 '돈 낼 마음 + 돈'으로 나눈다. 줄 서기는 '기다릴 마음 + 시간'으로 나눈다."},{"id":"L14:4","text":"그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","paragraph":0,"memberIds":["L14:4"],"topic":"그리고 '돈을 내겠다는 마음'이 '기다리겠다는 마음'보다 더 좋은 기준이라고 볼 이유는 없다."}]}]},"editorSourceVersion":"2ae309e96e022e675c5a186322087384106ff7f1d17557a84e1e4564f2686c23"},{"id":"U22-E08-B2","type":"ox","answer":"X","changed":"줄 서기는 기다리려는 마음만 중요하다. 실제로 기다릴 수 있는 시간은 중요하지 않다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"가람은 돈이 많아 경매에서 유리하고, 나래는 시간이 많아 줄 서기에서 유리해요. 돈을 내고 싶어도 돈이 없을 수 있고, 기다리고 싶어도 시간이 없을 수 있어요.","paragraphCount":2,"readingLabel":"14문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 14문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 14문단]\n암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다. 맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다. 시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다. 그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n한정된 물건을 경매로 나누거나 줄을 세워 나누려 한다. 가람은 돈이 많지만 기다릴 시간이 없고, 나래는 돈은 적지만 기다릴 시간이 많다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["비교"],"evidence":{"title":"돈이 많을 때와 시간이 많을 때","statement":"줄 서기는 기다리려는 마음과 실제로 기다릴 수 있는 시간이 함께 중요하다.","explanation":"가람은 돈이 많아 경매에서 유리하고, 나래는 시간이 많아 줄 서기에서 유리해요. 돈을 내고 싶어도 돈이 없을 수 있고, 기다리고 싶어도 시간이 없을 수 있어요.","valid":["L14:2","L14:3","L14:4"],"sources":[{"id":"L14","title":"줄 서기를 돈으로 살 수 있을까","label":"14문단","sentences":[{"id":"L14:1","text":"암표 거래를 옹호하는 사람들은 줄 서기가 시간이 남아도는 사람들에게 유리한 차별이라고 비판한다.","paragraph":0,"memberIds":["L14:1"],"topic":"암표 거래를 옹호하는 사람들은 “줄 서기도 시간이 많은 사람에게 유리한 차별이다”라고 비판한다."},{"id":"L14:2","text":"맞는 말이지만, 시장이 돈 많은 사람들을 유리하게 차별한다는 말과 같은 맥락에서만 그러하다.","paragraph":0,"memberIds":["L14:2"],"topic":"필자는 그 지적을 인정한다. 다만 시장도 돈 많은 사람에게 유리하므로, 줄 서기에만 있는 문제는 아니라고 말한다."},{"id":"L14:3","text":"시장이 자발적으로 돈을 지불하려는 마음과 능력을 바탕으로 재화를 분배하듯, 줄 서기는 자발적으로 기다리려는 마음과 능력을 바탕으로 재화를 분배한다.","paragraph":0,"memberIds":["L14:3"],"topic":"시장은 '돈 낼 마음 + 돈'으로 나눈다. 줄 서기는 '기다릴 마음 + 시간'으로 나눈다."},{"id":"L14:4","text":"그리고 자발적으로 가격을 지불하려는 마음이, 자발적으로 줄을 서서 기다리려는 마음보다 더 나은 가치 평가 기준이라고 추정할 근거는 없다.","paragraph":0,"memberIds":["L14:4"],"topic":"그리고 '돈을 내겠다는 마음'이 '기다리겠다는 마음'보다 더 좋은 기준이라고 볼 이유는 없다."}]}]},"claimEdits":[{"start":12,"end":22,"before":"마음만 중요하다. ","after":"마음과 "},{"start":35,"end":47,"before":"시간은 중요하지 않다.","after":"시간이 함께 중요하다."}],"editorSourceVersion":"58f6750bf1b174083db2f68b6cb3ce5c06f1a0e60b541c0c7aeb5bb39ccabf44"}]}],"cat":"2-2단원"};})(window);
